//! Identifier classes, punctuation and display widths, from tables generated by
//! `cargo xtask sync unicode`.

mod ident_tables;
mod punctuation_tables;
mod width_tables;

use std::cmp::Ordering;

pub use ident_tables::UNICODE_VERSION;

// Both tables must come from the same Unicode version; a half-regenerated pair does not build.
const _: () = assert!(
  ident_tables::UNICODE_VERSION.0 == width_tables::UNICODE_VERSION.0
    && ident_tables::UNICODE_VERSION.1 == width_tables::UNICODE_VERSION.1
    && ident_tables::UNICODE_VERSION.2 == width_tables::UNICODE_VERSION.2,
  "identifier and width tables come from different Unicode versions"
);

const _: () = assert!(
  ident_tables::UNICODE_VERSION.0 == punctuation_tables::UNICODE_VERSION.0
    && ident_tables::UNICODE_VERSION.1 == punctuation_tables::UNICODE_VERSION.1
    && ident_tables::UNICODE_VERSION.2 == punctuation_tables::UNICODE_VERSION.2,
  "identifier and punctuation tables come from different Unicode versions"
);

/// The number of terminal columns `c` occupies: 0, 1 or 2.
///
/// Control characters count as 0; expanding tabs is the caller's job.
pub fn char_width(c: char) -> usize {
  if c.is_ascii() {
    if c.is_ascii_control() { 0 } else { 1 }
  } else if c.is_control() || in_table(width_tables::ZERO_WIDTH, c) {
    0
  } else if in_table(width_tables::DOUBLE_WIDTH, c) {
    2
  } else {
    1
  }
}

/// True if `c` may continue a Rust identifier: XID_Continue.
pub fn is_ident_continue(c: char) -> bool {
  if c.is_ascii() {
    c.is_ascii_alphanumeric() || c == '_'
  } else {
    in_table(ident_tables::XID_CONTINUE, c)
  }
}

/// True if `c` may start a Rust identifier: XID_Start, or `_`.
pub fn is_ident_start(c: char) -> bool {
  if c.is_ascii() {
    c.is_ascii_alphabetic() || c == '_'
  } else {
    in_table(ident_tables::XID_START, c)
  }
}

/// True if `c` is other punctuation (general category Po), where the standard formatter
/// may break a comment's line.
pub fn is_other_punctuation(c: char) -> bool {
  in_table(punctuation_tables::OTHER_PUNCTUATION, c)
}

/// The width of `text` as the standard formatter measures it: tabs count 1, other control
/// characters 0.
pub fn str_width(text: &str) -> usize {
  text
    .chars()
    .map(|c| if c == '\t' { 1 } else { char_width(c) })
    .sum()
}

fn in_table(table: &[(u32, u32)], c: char) -> bool {
  let cp = c as u32;
  table
    .binary_search_by(|&(lo, hi)| {
      if hi < cp {
        Ordering::Less
      } else if lo > cp {
        Ordering::Greater
      } else {
        Ordering::Equal
      }
    })
    .is_ok()
}

#[cfg(test)]
mod tests {
  use super::*;

  fn all_chars() -> impl Iterator<Item = char> {
    (0..=0x10FFFFu32).filter_map(char::from_u32)
  }

  /// Walks every scalar value alongside the table, so a lookup bug cannot hide behind itself.
  fn assert_lookup_matches_walk(name: &str, table: &[(u32, u32)]) {
    let mut range = 0;
    for c in all_chars() {
      let cp = c as u32;
      while range < table.len() && table[range].1 < cp {
        range += 1;
      }
      let expected = range < table.len() && table[range].0 <= cp;
      assert_eq!(
        in_table(table, c),
        expected,
        "{} lookup disagrees at U+{:04X}",
        name,
        cp
      );
    }
  }

  fn assert_well_formed(name: &str, table: &[(u32, u32)]) {
    for (idx, &(lo, hi)) in table.iter().enumerate() {
      assert!(lo <= hi, "{} range {} is reversed", name, idx);
      if idx > 0 {
        assert!(
          table[idx - 1].1 + 1 < lo,
          "{} ranges {} and {} touch or overlap",
          name,
          idx - 1,
          idx
        );
      }
    }
  }

  #[test]
  fn test_ascii_fast_path_matches_tables() {
    for c in (0u8..=127).map(char::from) {
      assert_eq!(
        is_ident_start(c),
        c == '_' || in_table(ident_tables::XID_START, c),
        "start {:?}",
        c
      );
      assert_eq!(
        is_ident_continue(c),
        in_table(ident_tables::XID_CONTINUE, c),
        "continue {:?}",
        c
      );
    }
  }

  #[test]
  fn test_display_widths() {
    let cases = [
      ('a', 1),
      (' ', 1),
      ('\t', 0),
      ('\u{7F}', 0),
      ('é', 1),
      ('中', 2),
      ('Ａ', 2),
      ('🦀', 2),
      ('\u{0301}', 0),
      ('\u{200B}', 0),
      ('\u{200D}', 0),
      ('\u{FE0F}', 0),
      ('\u{1160}', 0),
      ('\u{11A8}', 0),
      ('\u{00AD}', 1),
      ('\u{FEFF}', 0),
    ];
    for (c, width) in cases {
      assert_eq!(char_width(c), width, "width of U+{:04X}", c as u32);
    }
    assert_eq!(str_width("fn 中文() {}"), 12);
    assert_eq!(str_width("e\u{0301}"), 1);
  }

  #[test]
  fn test_every_range_edge() {
    for table in [
      ident_tables::XID_START,
      ident_tables::XID_CONTINUE,
      width_tables::ZERO_WIDTH,
      width_tables::DOUBLE_WIDTH,
    ] {
      for &(lo, hi) in table {
        for (cp, inside) in [
          (lo, true),
          (hi, true),
          (lo.wrapping_sub(1), false),
          (hi + 1, false),
        ] {
          if let Some(c) = char::from_u32(cp) {
            assert_eq!(in_table(table, c), inside, "edge U+{:04X}", cp);
          }
        }
      }
    }
  }

  #[test]
  fn test_identifier_classes() {
    for c in ['a', 'Z', '_', 'é', 'ℵ', '中', 'Ω', 'ｱ'] {
      assert!(is_ident_start(c), "{:?} should start an identifier", c);
    }
    for c in ['0', '9', '·', '\u{0301}', '\u{0660}'] {
      assert!(!is_ident_start(c), "{:?} should not start an identifier", c);
      assert!(
        is_ident_continue(c),
        "{:?} should continue an identifier",
        c
      );
    }
    for c in ['-', ' ', '🦀', '€', '\u{200B}'] {
      assert!(
        !is_ident_start(c) && !is_ident_continue(c),
        "{:?} is not an identifier char",
        c
      );
    }
  }

  #[test]
  fn test_lookup_agrees_with_linear_walk_for_every_char() {
    assert_lookup_matches_walk("XID_START", ident_tables::XID_START);
    assert_lookup_matches_walk("XID_CONTINUE", ident_tables::XID_CONTINUE);
    assert_lookup_matches_walk("ZERO_WIDTH", width_tables::ZERO_WIDTH);
    assert_lookup_matches_walk("DOUBLE_WIDTH", width_tables::DOUBLE_WIDTH);
  }

  #[test]
  fn test_tables_are_sorted_and_disjoint() {
    assert_well_formed("XID_START", ident_tables::XID_START);
    assert_well_formed("XID_CONTINUE", ident_tables::XID_CONTINUE);
    assert_well_formed("ZERO_WIDTH", width_tables::ZERO_WIDTH);
    assert_well_formed("DOUBLE_WIDTH", width_tables::DOUBLE_WIDTH);
  }

  /// The tables keep up with the toolchain's Unicode. An older toolchain (the minimum
  /// supported Rust) knows an older one, which the tables are ahead of.
  #[test]
  fn test_tables_keep_up_with_the_toolchain_unicode_version() {
    let toolchain = char::UNICODE_VERSION;
    let toolchain = (toolchain.0, toolchain.1, toolchain.2);
    assert!(
      ident_tables::UNICODE_VERSION >= toolchain,
      "identifier tables are out of date: run `cargo xtask sync unicode`"
    );
    assert!(
      width_tables::UNICODE_VERSION >= toolchain,
      "width tables are out of date: run `cargo xtask sync unicode`"
    );
  }
}
